@spec arrange_page_spec  src=tests/specs/arrange_page_spec.lua  loc=1146  cases=48
@exercises commandManager (h.cmgr), configManager (h.cm), arrangeManager (am)
@surface   cmgr:registerAll, cm:set, cmgr:push, am:tracksTakes, cmgr:invoke, cm:get, am:resizeTake, am:trimHead, am:trackSlots
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.SetMediaItemSelected, reaper:setCursor

# Intent
  Pin-tests for arrangePage's Page interface and arrange-scope edit commands.
  Cursor mechanics, off-screen no-op, and selection-precedence: arrange_view_spec.

# Helpers
  @fn newArrangePage(cm, ds, cmgr, chrome, gui)  @ 49-57
  @fn twoSelected(h)  @ 61-80
      -- Two instances of slot 0, one row each at QN 0 and 1, with rows 0..1 banded.
      -- The siblings at QN 10 and 20 are what slots 0 and 1 clone from.

# Cases
  @case 'bind / unbind are no-ops — arrange page never re-keys cm'  [harness]  @ 84-94
  @case 'the arrange facade enumerates the takes over a span of columns and QN'  [harness]  @ 100-129
  @case 'focusState before any render returns both bits false'  [harness]  @ 133-140
  @case 'arrange-scope is registered at module load (cursorRight invokable)'  [harness]  @ 144-151
  @case 'arrange-scope place commands are registered (drop0/dropA/dropZ invokable)'  [harness]  @ 155-166
  @case 'a place-command drop advances the cursor by cm.arrangeAdvanceBy rows'  [harness]  @ 170-193
  @case 'arrangeAdvanceBy0..9 set cm.arrangeAdvanceBy at project tier'  [harness]  @ 197-208
  @case 'chained Super-D walks down — each clone becomes the selection for the next'  [harness]  @ 212-231
  @case 'a place-command drop inherits the length of an existing instance'  [harness]  @ 235-257
  @case 'arrangeNudgeForward moves the cursor take by one row'  [harness]  @ 261-275
  @case 'arrangeNudgeForward moves a take taller than one row'  [harness]  @ 279-294
  @case 'arrangeEdgeDown lengthens the cursor take by one row'  [harness]  @ 298-316
  @case 'growing a trimmed take moves its end, leaving the head where it was'  [harness]  @ 320-342
  @case 'arrangeEdgeDown silently no-ops at the take-source length cap'  [harness]  @ 346-361
  @case 'arrangeEdgeUp reduces the cursor take by one row'  [harness]  @ 365-381
  @case 'arrangeDeleteTake removes the cursor take'  [harness]  @ 385-399
  @case 'deleteSlot forever-deletes the cursor take\'s slot behind a confirm'  [harness]  @ 405-429
  @case 'deleteSlot no-ops with the cursor off every take'  [harness]  @ 433-449
  @case 'arrangeNudgeForward is a no-op when the next row is occupied'  [harness]  @ 453-469
  @case 'arrangeNudgeBack is a no-op when the take is already at row 0'  [harness]  @ 473-487
  @case 'arrangeEdgeDown against a flush neighbour stores intent; rendered is gap-capped'  [harness]  @ 491-510
  @case 'arrangeNudgeForward steps past a neighbour without a start-collision'  [harness]  @ 514-534
  @case 'arrangeNudgeForward truncates the displaced take when stepping past'  [harness]  @ 538-560
  @case 'arrangeDive switches to the tracker for the cursor MIDI take'  [harness]  @ 564-579
  @case 'createSlot dives the tracker onto the freshly-minted take'  [harness]  @ 583-598
  @case 'arrangeDive over an audio take still switches and restores (no take pinned)'  [harness]  @ 602-616
  @case 'arrangeDive over empty space switches and restores'  [harness]  @ 620-632
  @case 'the dive carries the caret QN, and carries none over empty space'  [harness]  @ 638-657
  @case 'kb edit acts on the cursor take when nothing is selected'  [harness]  @ 661-679
  @case 'kb delete no-ops when the cursor sits off every take'  [harness]  @ 683-701
  @case 'kb nudge no-ops when cursor sits on empty space'  [harness]  @ 705-722
  @case 'an edit command is a no-op when the cursor is over empty space'  [harness]  @ 726-741
  @case 'a second delete finds an empty cell under the cursor — no-op'  [harness]  @ 745-763
  @case 'seedCursorFromReaper lands the cursor on the selected take'  [harness]  @ 767-784
  @case 'seedCursorFromReaper falls back to the edit-cursor row'  [harness]  @ 788-802
  @case 'arrangeTakeProperties routes the focused MIDI take through the tracker facade'  [harness]  @ 811-824
  @case 'arrangeTakeProperties is a no-op on an audio take'  [harness]  @ 828-841
  @case 'arrangeDuplicateBelow drops a pooled clone at the focused take\'s append point'  [harness]  @ 845-861
  @case 'arrangeDuplicateBelow is silent for want of room and on audio takes'  [harness]  @ 865-883
  @case 'arrangeNextVariant past the last of the family swaps the target for a fresh variant'  [harness]  @ 887-918
  @case 'arrangeDuplicateBelow then arrangeNextVariant forks the copy onto a fresh slot'  [harness]  @ 924-948
  @case 'replace mode: a drop swaps the take under the cursor, keeping its start'  [harness]  @ 954-981
  @case 'a replace with a selection held replaces every selected take'  [harness]  @ 985-1002
  @case 'the replacements become the selection'  [harness]  @ 1006-1018
  @case 'a shorter replacement pulls the cursor back inside it'  [harness]  @ 1022-1050
  @case 'replace mode disarms on the drop it reinterprets — the next drop places'  [harness]  @ 1054-1082
  @case 'a cursor move disarms replace mode'  [harness]  @ 1086-1112
  @case 'a second arrangeReplaceMode disarms — the mode is a toggle'  [harness]  @ 1116-1143

